import { describeEvidenceBrief, reportHeadline, storedRootCause } from "./evidence-brief-summary";

// The brief format stored before this change (the one pre-filled into the resolve dialog).
const LEGACY_BRIEF = `# Incident Investigation Report

## Report Details
- **Incident**: Checkout: Job Failed
- **Severity**: sev2
- **Evidence Items**: 5

## Executive Summary
The checkout job failed in two runs, confirmed by the alert and the run records.
Confidence is high.

## What Changed
- Evidence ID: 01a111b9-8fa5-7c48-875e-f9be4ff9ba9c (Alert event)

---
**Generated by Supercheck AI.**`;

describe("storedRootCause", () => {
  it("reduces a stored report to its headline and keeps a conclusion whole", () => {
    expect(storedRootCause(LEGACY_BRIEF)).toBe(reportHeadline(LEGACY_BRIEF, 2000));
    expect(storedRootCause("Deploy 42 caused it.\n\nRollback restored checks.")).toBe("Deploy 42 caused it.\n\nRollback restored checks.");
    expect(storedRootCause("Pool exhausted [01a111b9-8fa5-7c48-875e-f9be4ff9ba9c].")).toBe("Pool exhausted.");
    expect(storedRootCause(null)).toBeNull();
    // An investigation conclusion that uses its own headings is not a legacy report.
    const conclusion = "## Cause\nDeploy 42.\n\n## Evidence\nError rate rose at 10:02.";
    expect(storedRootCause(conclusion)).toBe(conclusion);
  });
});

describe("reportHeadline", () => {
  it("takes the executive summary of a legacy report and drops the header fields", () => {
    expect(reportHeadline(LEGACY_BRIEF)).toBe(
      "The checkout job failed in two runs, confirmed by the alert and the run records. Confidence is high.",
    );
  });

  it("reads the new Summary section", () => {
    expect(reportHeadline("## Summary\nThe **job** timed out.\n\n## Impact\nUnknown.")).toBe("The job timed out.");
  });

  it("falls back to the first prose paragraph after a title and field lines", () => {
    const triage = "**Incident Classification**\n- **Incident**: Checkout down\n- **Severity**: sev2\n\nThe pool is exhausted (01a111b9-8fa5-7c48-875e-f9be4ff9ba9c).";
    expect(reportHeadline(triage)).toBe("The pool is exhausted.");
    expect(reportHeadline("# Incident Report: Checkout\n\nDeploy 42 broke login.")).toBe("Deploy 42 broke login.");
  });

  it("keeps plain text, and uses field values when nothing else is prose", () => {
    expect(reportHeadline("Latency correlates with monitor failures.")).toBe("Latency correlates with monitor failures.");
    expect(reportHeadline("**Likely cause**: DNS change")).toBe("Likely cause: DNS change");
  });

  it("keeps a bold conclusion and skips only bold report titles", () => {
    expect(reportHeadline("**Database pool exhausted**\n\nConnections hit the limit at 10:02.")).toBe("Database pool exhausted");
    expect(reportHeadline("**Incident Analysis Report**\n\nThe pool is exhausted.")).toBe("The pool is exhausted.");
  });

  it("keeps labelled findings that model output often starts with", () => {
    expect(reportHeadline("**Initial classification:** Likely DB connectivity failure.\n\n**Likely failure domains:**\n- Database")).toBe(
      "Initial classification: Likely DB connectivity failure.",
    );
    expect(reportHeadline("**Root cause:** DB pool is exhausted after deploy.\n\nCheck pool metrics next.")).toBe(
      "Root cause: DB pool is exhausted after deploy.",
    );
    expect(reportHeadline("**Summary:** DB failed over.\n\nMore")).toBe("DB failed over.");
    expect(reportHeadline("1. **Initial classification**: Network timeout.\n2. **Domains**: DNS")).toBe(
      "Initial classification: Network timeout. Domains: DNS",
    );
  });

  it("returns null for empty input and clips long text on a word boundary", () => {
    expect(reportHeadline(null)).toBeNull();
    expect(reportHeadline("  ")).toBeNull();
    const clipped = reportHeadline("word ".repeat(200), 50)!;
    expect(clipped.length).toBeLessThanOrEqual(51);
    expect(clipped.endsWith("word…")).toBe(true);
  });
});

describe("describeEvidenceBrief", () => {
  it("summarises the brief fields", () => {
    expect(describeEvidenceBrief({ suspectedFailureDomain: "deploy", evidenceCount: 1, confidenceScore: 0.5 })).toBe(
      "1 evidence item reviewed; suspected failure domain: deploy; confidence 50%.",
    );
  });
  it("falls back when fields are missing", () => {
    expect(describeEvidenceBrief({})).toBe("Evidence brief generated.");
  });
  it("keeps zero values and drops non-finite confidence", () => {
    expect(describeEvidenceBrief({ evidenceCount: 0, confidenceScore: 0 })).toBe("0 evidence items reviewed; confidence 0%.");
    expect(describeEvidenceBrief({ evidenceCount: 2, confidenceScore: NaN })).toBe("2 evidence items reviewed.");
    expect(describeEvidenceBrief({ evidenceCount: 2, confidenceScore: Infinity })).toBe("2 evidence items reviewed.");
  });
});
